INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT144-S2-Q1$batch13$, 144, 2, 1, $batch13$Flaw$batch13$, $batch13$In the bodies of reptiles, some industrial by-products cause elevated hormonal activity. Hormones govern the development of certain body parts, and in reptiles abnormal development of these parts occurs only with elevated hormonal activity. Recently, several alligators with the telltale developmental abnormalities were discovered in a swamp. So, apparently, industrial by-products have entered the swamp’s ecosystem.$batch13$, $batch13$The reasoning in the argument is most vulnerable to criticism on the grounds that the argument$batch13$, $batch13$B$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=144 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q1$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$provides no explanation for developmental abnormalities that do not result from elevated hormonal activity$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$fails to consider whether elevated hormonal activity can result from factors other than the presence of industrial by-products$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$fails to address the possibility that industrial by-products were contained in food the alligators ate$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$fails to say whether reptiles other than alligators were examined for the same developmental abnormalities that were discovered in the alligators$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$uses evidence drawn from a sample of alligators that is unlikely to be representative of alligators in general$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$Industrial by-products have probably entered the swamp's ecosystem.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Some industrial by-products raise hormone activity in reptiles. In reptiles, these abnormalities occur only with elevated hormone activity. Alligators with the abnormalities were found in the swamp.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$The abnormalities prove elevated hormones, since they occur only with them. But the argument then jumps from elevated hormones to by-products. By-products are one cause of elevated hormones. Nothing says they're the only cause.$batch13$), (3, $batch13$Goal$batch13$, $batch13$The argument ignores other causes of elevated hormone activity.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT144-S2-Q1$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The premise says these abnormalities occur only with elevated hormones. No other explanation is needed.$batch13$), ($batch13$B$batch13$, $batch13$Something else could have raised the hormones, and then by-products wouldn't be needed.$batch13$), ($batch13$C$batch13$, $batch13$By-products in the alligators' food would still be by-products in the ecosystem. That supports the conclusion.$batch13$), ($batch13$D$batch13$, $batch13$Other reptiles don't matter. The alligators are enough to show elevated hormones.$batch13$), ($batch13$E$batch13$, $batch13$The conclusion is about this swamp, not alligators in general.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT144-S2-Q1$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
